def validate_trace(spans):
    ids = {span.span_id for span in spans}
    if len(ids) != len(spans):
        return False, 'DUPLICATE_SPAN_ID'
    trace_ids = {span.trace_id for span in spans}
    if len(trace_ids) != 1:
        return False, 'MIXED_TRACE_IDS'
    for span in spans:
        if span.end_ms < span.start_ms:
            return False, 'NEGATIVE_DURATION'
        if span.parent_id and span.parent_id not in ids:
            return False, 'MISSING_PARENT'
    return True, 'VALID'
